import * as E from './engine.js';
import {seasonAt,seasonalFactors} from './procedural.js';
export function diplomacyPanel(s,h){
 const {head,esc,cost,clock}=h,c=E.civilization(s),season=seasonAt(s.time);
 const races='<div class="race-grid">'+Object.entries(E.RACES).map(([id,r])=>'<article class="race-card '+(c.race===id?'chosen':'')+'"><img src="./auralis/icons/'+id+'.svg" alt="" width="66" height="66"><div><small>'+esc(r.title)+'</small><h3>'+esc(r.name)+'</h3><p>'+esc(r.description)+'</p><b>'+esc(r.bonus)+'</b></div>'+(!c.race?'<button class="primary" data-action="race-choose" data-type="'+id+'">Elegir '+esc(r.name)+'</button>':c.race===id?'<span class="civilization-tag">Tu civilización</span>':'')+'</article>').join('')+'</div>';
 if(!c.race)return head('CIVILIZACIÓN · ELECCIÓN PERMANENTE','El origen de tu pueblo')+'<p>Elige tu raza. Conservas la base, las tropas y los materiales que ya tienes. Cada raza ofrece una ventaja; después podrás negociar con cualquiera de sus clanes.</p>'+races+'<p class="tiny">Esta elección se guarda con tu partida. Las alianzas son con personajes de la IA local.</p>';
 const relations=Object.values(c.relations),allies=relations.filter(r=>r.status==='ally').length,wars=relations.filter(r=>r.status==='war').length;
 const morality='<section class="morality-card"><img src="./auralis/icons/'+c.race+'.svg" width="60" height="60" alt=""><div><small>'+esc(E.RACES[c.race].name)+'</small><h3>'+E.honorName(s)+' · '+c.morality+'</h3><meter min="-100" max="100" value="'+c.morality+'" aria-label="Moralidad">'+c.morality+'</meter><p>'+allies+' alianzas · '+wars+' guerras. Ayudar a civiles mejora tu moralidad. Saquear y traicionar perjudica la confianza y las alianzas.</p></div></section>';
 const dilemmas=c.decisions.map(d=>'<article class="moral-decision"><small>DESPUÉS DE LA VICTORIA</small><h3>'+esc(d.name)+'</h3><p>Los civiles de '+esc(E.factionById(d.faction).name)+' esperan tu decisión.</p><div class="action-row"><button data-action="moral-choice" data-id="'+d.id+'" data-type="protect">Proteger civiles · moralidad +6</button><button data-action="moral-choice" data-id="'+d.id+'" data-type="plunder">Requisar '+(100+d.level*50)+' oro · moralidad −10</button></div></article>').join('');
 const factions=Object.entries(E.RACES).map(([race,def])=>{const list=E.FACTIONS.filter(f=>f.race===race),known=list.some(f=>E.relation(s,f.id));return'<section class="faction-group"><header><h3>'+esc(def.name)+'</h3>'+(known?'<div class="action-row"><button data-action="diplo-race" data-id="'+race+'" data-type="ally">Alianza con ambos clanes</button><button class="danger" data-action="diplo-race" data-id="'+race+'" data-type="war">Guerra con ambos clanes</button></div>':'')+'</header><div class="faction-grid">'+list.map(f=>{const r=E.relation(s,f.id),q=E.tradeQuote(s,f.id);return'<article class="faction-card" data-faction="'+f.id+'"><div class="faction-heading"><img src="./auralis/icons/'+f.race+'.svg" width="48" height="48" alt=""><div><h4>'+esc(f.name)+'</h4><small>'+esc(f.clan)+' · '+f.temper+'</small></div><span class="relation '+(r?.status||'unknown')+'">'+(!r?'Sin contacto':r.status==='war'?'Guerra':r.status==='ally'?'Alianza':'Neutral')+'</span></div>'+(!r?'<p>Reconoce nuevas islas para encontrar a este clan.</p>':'<p>Reputación <b>'+r.reputation+' / 100</b></p><div class="trade-offer"><small>ENTREGAS</small>'+cost(q.cost)+'<small>RECIBES</small>'+cost(q.reward)+'</div><button class="wide" data-action="diplo-action" data-id="'+f.id+'" data-type="trade" '+(!q.ok?'disabled':'')+'>'+(q.remaining?'Caravana en '+clock(q.remaining):'Aceptar trato · reputación +6')+'</button><div class="action-row"><button data-action="diplo-action" data-id="'+f.id+'" data-type="aid" '+(r.status==='war'||s.time<r.aidAt?'disabled':'')+'>Ayuda: 60 madera + 40 petróleo</button>'+(r.status==='war'?'<button data-action="diplo-action" data-id="'+f.id+'" data-type="peace">Pedir tregua · 200 oro + 100 petróleo</button>':r.status==='neutral'?'<button data-action="diplo-action" data-id="'+f.id+'" data-type="ally" '+(r.reputation<20?'disabled':'')+'>Alianza · 100 oro</button>':'')+(r.status!=='war'?'<button class="danger" data-action="diplo-action" data-id="'+f.id+'" data-type="war">Declarar guerra</button>':'')+'</div>')+'</article>';}).join('')+'</div></section>';}).join('');
 return head('RAZAS, CLANES Y FACCIONES NPC','Civilización y diplomacia')+morality+dilemmas+'<p>Un trato necesita espacio en tus reservas y tiene cinco minutos de espera. Las alianzas necesitan reputación 20 y un centro diplomático. Los aliados permiten fundar puestos por acuerdo. La guerra permite atacar sus islas y aumenta la presión de las incursiones.</p><section class="season-card"><img src="./auralis/icons/season.svg" width="44" height="44" alt=""><div><h3>'+season.name+' · Año '+season.year+'</h3><p>Día '+season.day+' · cambio en '+clock(season.remaining)+'. En biomas templados, la madera colonial rinde '+Math.round(seasonalFactors('wood','forest')[season.index]*100)+'%. En invierno el transporte marítimo tarda un 25% más.</p></div></section>'+factions+'<details><summary>Tu raza y las demás civilizaciones</summary>'+races+'</details><details><summary>Historia de acuerdos</summary>'+c.history.slice(0,12).map(e=>'<p class="tiny">'+esc(e.message)+'</p>').join('')+'</details>';
}
